#include <Arduino.h>

const uint8_t selectPins[4] = {2, 3, 4, 5};

int readChannel(uint8_t channel) {
  for (uint8_t bit = 0; bit < 4; ++bit) {
    digitalWrite(selectPins[bit], (channel >> bit) & 1);
  }
  delayMicroseconds(20);
  analogRead(A0);
  return analogRead(A0);
}

void setup() {
  for (uint8_t bit = 0; bit < 4; ++bit) {
    pinMode(selectPins[bit], OUTPUT);
    digitalWrite(selectPins[bit], LOW);
  }
  Serial.begin(9600);
}

void loop() {
  for (uint8_t channel = 0; channel < 6; ++channel) {
    int value = readChannel(channel);
    Serial.print("Sensor ");
    Serial.print(channel);
    Serial.print(": ");
    Serial.println(value);
  }
  delay(100);
}
